var ConfigRefreshRWMutex sync.RWMutex

func startConfigRefresher(URL string) {
	slog.Info("starting config refresher each 10 minutes")

	ticker := time.NewTicker(10 * time.Minute)

	go func() {
		// on panic - log and restart the ticker
		defer func() {
			if r := recover(); r != nil {
				slog.Error("recovered from panic", "err", r)
				ConfigRefreshRWMutex.Unlock()
				startConfigRefresher(URL)
			}
		}()

		for range ticker.C {
			ConfigRefreshRWMutex.Lock()
			slog.Info("config tick", "time", time.Now())
			fetchAndApplyRemoteConfig(URL)
			// refresh the svg URLs
			RuntimeConfig = rewriteBadgeSvgURLs(RuntimeConfig)
			// reload all manual observers
			for _, badge := range RuntimeConfig.Badges {
				for _, level := range badge.Levels {
				checkLoop:
					for _, check := range level.Checks {
						if check.Type == observe.MANUAL_TYPE {
							observer, err := loadManualObserver(check)
							if err != nil {
								// just log the error
								slog.Error("could not load manual observer. It will be retried in 5 minutes", "err", err)
								continue
							}

							// check if the observer is already in the cache - then we need to replace it
							for i, o := range observerCache {
								if o.Key() == observer.Key() {
									observerCache[i] = observer
									slog.Info("reloaded manual observer", "key", observer.Key())
									continue checkLoop
								}
							}
							// we need to append the observer
